  "locator": "extracted HTML block 1",
  "segments": [
    {
      "segment_id": "S00001",
      "start_char": 0,
      "end_char": 161,
      "text": "ACUERDO por el que se dan a conocer los porcentajes, los montos del estímulo fiscal y las cuotas disminuidas del impuesto especial sobre producción y servicios, "
    },
    {
      "segment_id": "S00002",
      "start_char": 161,
      "end_char": 308,
      "text": "así como las cantidades por litro aplicables a los combustibles que se indican, correspondien\nACUERDO por el que se dan a conocer los porcentajes, "
    },
    {
      "segment_id": "S00003",
      "start_char": 308,
      "end_char": 543,
      "text": "los montos del estímulo fiscal y las cuotas disminuidas del impuesto especial sobre producción y servicios, así como las cantidades por litro aplicables a los combustibles que se indican, correspondientes al periodo que se especifica.\n"
    },
    {
      "segment_id": "S00004",
      "start_char": 543,
      "end_char": 676,
      "text": "Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- HACIENDA.- Secretaría de Hacienda y Crédito Público.\n"
    },
    {
      "segment_id": "S00005",
      "start_char": 676,
      "end_char": 854,
      "text": "Acuerdo 173/2022 Acuerdo por el que se dan a conocer los porcentajes, los montos del estímulo fiscal y las cuotas disminuidas del impuesto especial sobre producción y servicios, "
    },
    {
      "segment_id": "S00006",
      "start_char": 854,
      "end_char": 981,
      "text": "así como las cantidades por litro aplicables a los combustibles que se indican, correspondientes al periodo que se especifica. "
    },
    {
      "segment_id": "S00007",
      "start_char": 981,
      "end_char": 1111,
      "text": "KARINA RAMÍREZ ARRAS, Titular de la Unidad de Política de Ingresos no Tributarios de la Secretaría de Hacienda y Crédito Público, "
    },
    {
      "segment_id": "S00008",
      "start_char": 1111,
      "end_char": 1331,
      "text": "con fundamento en lo dispuesto por el artículo Primero del Decreto por el que se est ablecen estímulos fiscales en materia del impuesto especial sobre producción y servicios aplicables a los combustibles que se indican, "
    },
    {
      "segment_id": "S00009",
      "start_char": 1331,
      "end_char": 1567,
      "text": "publicado en el Diario Oficial de la Federación el 27 de diciembre de 2016 y sus posteriores modificaciones, y el artículo Primero del Decreto por el que se establecen estímulos fiscales complementarios a los combustibles automotrices, "
    },
    {
      "segment_id": "S00010",
      "start_char": 1567,
      "end_char": 1780,
      "text": "publicado en el Diario Oficial de la Federación el 4 de marzo de 2022, se dan a conocer los porcentajes, los montos del estímulo fiscal y las cuotas disminuidas del impuesto especial sobre producción y servicios, "
    },
    {
      "segment_id": "S00011",
      "start_char": 1780,
      "end_char": 1998,
      "text": "así como las cantidades por litro aplicables a los combustibles automotrices, respectivamente, correspondientes al periodo comprendido del 10 al 16 de diciembre de 2022, mediante el siguiente ACUERDO Artículo Primero. "
    },
    {
      "segment_id": "S00012",
      "start_char": 1998,
      "end_char": 2159,
      "text": "Los porcentajes del estímulo fiscal para el periodo comprendido del 10 al 16 de diciembre de 2022, aplicables a los combustibles automotrices son los siguientes:"
    }
  ]
}

