{
  "schema_version": "locator_index_v1",
  "source_id": "LAW-005",
  "source_sha256": "9284e94294ac9d6e565c3186433b2b7b26efb621396d3bc2850cfa654277db3d",
  "locator": "extracted HTML block 2",
  "segments": [
    {
      "segment_id": "S00001",
      "start_char": 0,
      "end_char": 152,
      "text": "Combustible Porcentaje de Estímulo\nGasolina menor a 91 octanos 26.96%\nGasolina mayor o igual a 91 octanos y combustibles no fósiles 0.00%\nDiésel 59.77%\n"
    },
    {
      "segment_id": "S00002",
      "start_char": 152,
      "end_char": 379,
      "text": "Artículo Segundo. Los montos del estímulo fiscal para el periodo comprendido del 10 al 16 de diciembre de 2022, aplicables a los combustibles automotrices son los siguientes:\nCombustible Monto del estímulo fiscal (pesos/litro)\n"
    },
    {
      "segment_id": "S00003",
      "start_char": 379,
      "end_char": 500,
      "text": "Gasolina menor a 91 octanos $1.4803\nGasolina mayor o igual a 91 octanos y combustibles no fósiles $0.0000\nDiésel $3.6071\n"
    },
    {
      "segment_id": "S00004",
      "start_char": 500,
      "end_char": 723,
      "text": "Artículo Tercero. Las cuotas para el periodo comprendido del 10 al 16 de diciembre de 2022, aplicables a los combustibles automotrices son las siguientes:\nCombustible Cuota (pesos/litro)\nGasolina menor a 91 octanos $4.0114\n"
    },
    {
      "segment_id": "S00005",
      "start_char": 723,
      "end_char": 963,
      "text": "Gasolina mayor o igual a 91 octanos y combustibles no fósiles $4.6375\nDiésel $2.4283\nArtículo Cuarto. Las cantidades por litro de estímulos complementarios aplicables a los combustibles automotrices durante el periodo comprendido del 10 al "
    },
    {
      "segment_id": "S00006",
      "start_char": 963,
      "end_char": 1168,
      "text": "16 de diciembre de 2022, son las siguientes:\nCombustible Cantidad por litro (pesos)\nGasolina menor a 91 octanos $0.0000\nGasolina mayor o igual a 91 octanos y combustibles no fósiles $0.0000\nDiésel $0.0000\n"
    },
    {
      "segment_id": "S00007",
      "start_char": 1168,
      "end_char": 1299,
      "text": "TRANSITORIO ÚNICO.- El presente Acuerdo entrará en vigor al día siguiente de su publicación en el Diario Oficial de la Federación. "
    },
    {
      "segment_id": "S00008",
      "start_char": 1299,
      "end_char": 1535,
      "text": "Ciudad de México, a 08 de diciembre de 2022 .- Con fundamento en el artículo Primero, último párrafo del Decreto por el que se establecen estímulos fiscales en materia del impuesto especial sobre producción y servicios aplicables a los "
    },
    {
      "segment_id": "S00009",
      "start_char": 1535,
      "end_char": 1727,
      "text": "combustibles que se indican, y el artículo Primero, último párrafo del Decreto por el que se establecen estímulos fiscales complementarios a los combustibles automotrices, en suplencia del C. "
    },
    {
      "segment_id": "S00010",
      "start_char": 1727,
      "end_char": 1870,
      "text": "Subsecretario de Hacienda y Crédito Público , la Titular de la Unidad de Política de Ingresos No Tributarios , Karina Ramírez Arras .- Rúbrica."
    }
  ]
}

